import re


def bulk_discount(qty):
    """Return the discount rate for an integer quantity.

    0.12 if qty >= 200; 0.04 if qty >= 25; otherwise 0.0.
    """
    if qty >= 200:
        return 0.12
    if qty >= 25:
        return 0.04
    return 0.0


def line_total(unit_price, qty):
    """Return unit_price * qty * (1 - bulk_discount(qty)), rounded to 2 decimals."""
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


_SKU_RE = re.compile(r"^([A-Z]{2,4})/(\d{4})/([A-Za-z])$")


def parse_sku(s):
    """Parse a SKU of the form CAT/1234/X.

    Category is 2-4 upper-case letters, number is 4 digits, variant is one letter.
    Raises ValueError for anything else.
    """
    if not isinstance(s, str):
        raise ValueError("invalid SKU: " + repr(s))
    m = _SKU_RE.match(s)
    if not m:
        raise ValueError("invalid SKU: " + s)
    return {"category": m.group(1), "number": int(m.group(2)), "variant": m.group(3)}

